UPDATE resolve_fixture SET competition_code = #{competitionCode}, competition_name = #{competitionName}, league_ref = #{leagueRef},
  home_name = #{homeName}, home_short = #{homeShort}, away_name = #{awayName}, away_short = #{awayShort}, kickoff_at = #{kickoffAt},
  primary_status = #{primaryStatus}, primary_raw_status = #{primaryRawStatus}, fetched_at = #{fetchedAt}, version = version + 1, updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE resolve_fixture SET backup_source = #{source}, backup_ref = #{ref}, backup_swapped = #{swapped}, backup_home = #{home}, backup_away = #{away},
  backup_kickoff_at = #{kickoff}, mapping_confirmed_by = #{by}, mapping_confirmed_at = #{now}, version = version + 1, updated_at = #{now}
WHERE id = #{id}

UPDATE resolve_fixture SET backup_source = NULL, backup_ref = NULL, backup_swapped = 0, backup_home = NULL, backup_away = NULL, backup_kickoff_at = NULL,
  mapping_confirmed_by = NULL, mapping_confirmed_at = NULL, version = version + 1, updated_at = #{now}
WHERE id = #{id} AND backup_ref IS NOT NULL

sql.where:
kickoff_at >= #{from} AND kickoff_at < #{to}
AND sport = #{sport}
AND backup_ref IS NOT NULL
AND backup_ref IS NULL

