UPDATE resolve_sports_task SET attempts = attempts + 1, next_attempt_at = #{next}, last_reason = #{reason}, last_attempt_at = #{now},
  version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND status = 'PENDING' AND version = #{version}

UPDATE resolve_sports_task SET attempts = attempts + 1, finished_seen_at = #{seen}, settle_after_at = #{settleAfter}, give_up_at = #{giveUp},
  next_attempt_at = #{settleAfter}, last_reason = #{reason}, last_attempt_at = #{now}, version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND status = 'PENDING' AND version = #{version} AND finished_seen_at IS NULL

UPDATE resolve_sports_task SET status = 'RESOLVING', attempts = attempts + 1, result_option_id = #{optionId}, actual_start_at = #{actualStartAt},
  next_attempt_at = #{next}, last_reason = #{reason}, last_attempt_at = #{now}, version = version + 1, updated_at = #{now}
WHERE market_id = #{marketId} AND status = 'PENDING' AND version = #{version}

UPDATE resolve_sports_task SET status = 'MANUAL', attempts = attempts + 1, last_reason = #{reason}, last_attempt_at = #{now}, version = version + 1,
  updated_at = #{now}
WHERE market_id = #{marketId} AND status = 'PENDING' AND version = #{version}

UPDATE resolve_sports_template SET name = #{t.name}, title_en = #{t.titleEn}, title_zh_cn = #{t.titleZhCn}, title_zh_tw = #{t.titleZhTw},
  rules_en = #{t.rulesEn}, rules_zh_cn = #{t.rulesZhCn}, rules_zh_tw = #{t.rulesZhTw}, source_primary = #{t.sourcePrimary},
  source_backup = #{t.sourceBackup}, options = #{t.options}, version = version + 1, updated_by = #{t.updatedBy}, updated_at = #{t.updatedAt}
WHERE kind = #{t.kind} AND version = #{oldVersion}
